  // 채팅:    api.chat.current() / send(text) / insert(text) / generate() / addSystemMessage(text) / redraw()
  // AI:      await api.ai.quick(시스템문, 사용자문)
  return () => { /* 끌 때 정리할 일 (등록한 것들은 자동으로 치워집니다) */ };
